def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]
    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n >= 10:
        recent_opp = opp[-10:]
        recent_d = recent_opp.count('D')
        if recent_d >= 8:
            return 'D'
        if recent_d == 0 and last_opp == 'C':
            if n >= 90:
                return 'C'
            return 'C'

    if n >= 3 and opp[-1] == 'D' and opp[-2] == 'D' and opp[-3] == 'D':
        return 'D'

    if n >= 4 and last_opp == 'D' and last_me == 'C' and opp_c * 3 < n:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if n >= 4 and opp[-4:].count('D') >= 3:
                return 'D'
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        else:
            if opp_d >= 8 and opp_c >= 2:
                return 'D'
            if rng.random() < 0.15:
                return 'D'
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 6 and n >= 25:
            if n >= 85:
                return 'C'
            if rng.random() < 0.1:
                return 'D'
        return 'C'

    return 'C'
